"""Results figures R1-R5 (graphic generated by code written by Claude (AI, chat), 2026-10-06).
Every number is copied from the committed source named next to it (checked by hand the same day).
Usage: python paper_template/figures/results_figs.py -> R1_gate.pdf ... R5_overlap.pdf"""
import numpy as np
import matplotlib.pyplot as plt
from matplotlib.patches import FancyBboxPatch
from figstyle import BLUE, ORANGE, AQUA, VIOLET, YELLOW, INK, INK2, GRID, FULL, save

LBLUE = "#d6e6f7"; SOFT = "#f4f4f2"
def style(ax):
    ax.grid(axis="x", color=GRID, lw=0.5); ax.set_axisbelow(True)

# ---------------------------------------------------------------- R1 gate
fig, (a, b) = plt.subplots(1, 2, figsize=(FULL, 2.7), gridspec_kw=dict(width_ratios=[1.25, 1], wspace=0.55))
# (a) decisions.md:1572-1586 (gate), :2717 (persistence hour)
rows = [("Gate, hourly", 0.5467, 0.4120, 0.6598, BLUE, "o", True),
        ("Persistence, hourly", 0.3576, 0.2435, 0.4613, INK2, "s", True),
        ("Gate, region level", 0.7284, 0.6301, 0.8198, BLUE, "o", True),
        ("Gate, hourly (incl. 2022)", 0.5224, 0.4115, 0.6256, BLUE, "o", False),
        ("Gate, region (incl. 2022)", 0.6812, 0.5841, 0.7621, BLUE, "o", False)]
y = np.arange(len(rows))[::-1]
a.axhspan(1.5, 4.5, color=LBLUE, alpha=0.35, lw=0)
for yy, (lab, v, lo, hi, c, m, f) in zip(y, rows):
    a.plot([lo, hi], [yy, yy], color=c, lw=1.6, solid_capstyle="round")
    a.plot(v, yy, m, ms=6.5, mfc=c if f else "white", mec=c, mew=1.4)
    a.text(hi + 0.012, yy, f"{v:.2f}", va="center", fontsize=7.5, color=INK)
a.set_yticks(y); a.set_yticklabels([r[0] for r in rows]); a.set_xlim(0.2, 0.95)
a.set_xlabel("TSS (95% CI, HARP bootstrap)"); style(a)
a.text(0.21, 4.55, "held-out 2021, 2023, 2024", fontsize=7, color=BLUE, va="bottom", style="italic")
a.text(0.21, 1.52, "pre-registered sensitivity, includes 2022", fontsize=7, color=INK2, va="bottom", style="italic")
a.set_title("(a) Frozen gate on held-out years", loc="left", fontsize=8.5)
# (b) decisions.md:1847 (published, D7/D8), :2244 (targets), :2252-2256 (R1-R4), :5715-5720 (R5-R7)
for k, (cw, pub, sd, tlo, thi, ours, osd, others) in enumerate([
        ("weight 2", 0.610, 0.048, 0.562, 0.658, 0.527, 0.050, [0.515, 0.520, 0.530, 0.507, 0.511, 0.510, 0.497]),
        ("weight 15", 0.761, 0.039, 0.722, 0.800, 0.716, 0.040, [0.706, 0.708, 0.695, 0.695, 0.744, 0.703, 0.738])]):
    x0 = k
    b.add_patch(plt.Rectangle((x0 - 0.32, tlo), 0.64, thi - tlo, color="#e9e3f5", lw=0, zorder=0))
    b.errorbar(x0 - 0.13, pub, yerr=sd, fmt="D", color=VIOLET, ms=6, capsize=2.5, lw=1.2, zorder=3)
    b.errorbar(x0 + 0.13, ours, yerr=osd, fmt="o", color=AQUA, ms=6, capsize=2.5, lw=1.2, zorder=3)
    b.scatter(np.full(len(others), x0 + 0.27), others, s=9, color=INK2, alpha=0.6, zorder=2)
b.set_xticks([0, 1]); b.set_xticklabels(["weight 2", "weight 15"]); b.set_xlim(-0.55, 1.55)
b.set_ylabel("TSS (mean ± sd, random splits)"); b.set_ylim(0.42, 0.84); b.grid(axis="y", color=GRID, lw=0.5)
b.plot([], [], "D", color=VIOLET, label="Bobra & Couvidat (published)")
b.plot([], [], "o", color=AQUA, label="our re-run (exploratory)")
b.scatter([], [], s=9, color=INK2, label="diagnostic variants")
b.add_patch(plt.Rectangle((0, 0), 0, 0, color="#e9e3f5", label="target range set in advance"))
b.legend(loc="upper center", bbox_to_anchor=(0.5, -0.13), fontsize=6.3, handlelength=1.2, ncol=2)
b.set_title("(b) Their protocol on our 2010–2014 data", loc="left", fontsize=8.5)
save(fig, "R1_gate", "results_figs.py")

# ---------------------------------------------------------------- R2 Path A
fig, (a, b) = plt.subplots(1, 2, figsize=(FULL, 2.6), gridspec_kw=dict(width_ratios=[1.6, 1], wspace=0.4))
# decisions.md:2438-2439 (2,000 HARP resamples, seed 0)
grp = [("hourly\n3,988 alarm hours", 0.8007, (0.7110, 0.8878), 0.7021, (0.6186, 0.7833), "0.099 [0.057, 0.150]"),
       ("region level\n105 alarmed regions", 0.7238, (0.6344, 0.8058), 0.5429, (0.4414, 0.6337), "0.181 [0.112, 0.259]")]
for i, (lab, h, hci, s, sci, d) in enumerate(grp):
    a.bar(i - 0.18, h, 0.34, color="#bfbfbb", edgecolor=INK2, lw=0.6)
    a.bar(i + 0.18, s, 0.34, color=BLUE, edgecolor=BLUE, lw=0.6)
    a.errorbar(i - 0.18, h, yerr=[[h - hci[0]], [hci[1] - h]], color=INK, capsize=2.5, lw=0.9)
    a.errorbar(i + 0.18, s, yerr=[[s - sci[0]], [sci[1] - s]], color=INK, capsize=2.5, lw=0.9)
    a.text(i - 0.18, hci[1] + 0.02, f"{h:.2f}", ha="center", fontsize=7.5)
    a.text(i + 0.18, sci[1] + 0.02, f"{s:.2f}", ha="center", fontsize=7.5, color=BLUE)
    a.text(i, 1.02, "HEK − SWPC\n" + d, ha="center", fontsize=6.8, color=INK2)
a.set_xticks([0, 1]); a.set_xticklabels([g[0] for g in grp]); a.set_ylim(0, 1.15); a.set_ylabel("false-alarm ratio (95% CI)")
from matplotlib.patches import Patch
a.legend(handles=[Patch(fc="#bfbfbb", ec=INK2, label="HEK labels"), Patch(fc=BLUE, label="SWPC labels (used)")], loc="upper center", bbox_to_anchor=(0.5, -0.2), fontsize=6.8, ncol=2); a.grid(axis="y", color=GRID, lw=0.5); a.set_axisbelow(True)
a.set_title("(a) False-alarm ratio, held-out years", loc="left", fontsize=8.5)
# decisions.md:2413 (2021: 2, 2023: 17), :2379 (2024: 0)
yrs, ph = ["2021", "2023", "2024"], [2, 17, 0]
b.bar(yrs, ph, color=[YELLOW, ORANGE, GRID], edgecolor=INK2, lw=0.5, width=0.6)
for xx, v in zip(yrs, ph): b.text(xx, v + 0.4, str(v), ha="center", fontsize=8, weight="bold")
b.set_ylabel("phantom false alarms\n(false with HEK, true with SWPC)"); b.set_ylim(0, 20); b.grid(axis="y", color=GRID, lw=0.5); b.set_axisbelow(True)
b.set_title("(b) Alarms turned false by HEK", loc="left", fontsize=8.5)
save(fig, "R2_patha", "results_figs.py")

# ---------------------------------------------------------------- R3 twins forest
# sources: phase_f_F2.log:7; euv_f2_replication.log:10,13; euv_extra_filter_test.log:16,30; euv_confirm_tests.log:5-8;
#          sensitivity_combined.log:16-17; posthoc_twin_reuse.log:6-8
S = {"conf": (BLUE, "o", True, "pre-registered, confirmatory"), "sec": (BLUE, "o", False, "pre-registered, secondary or sensitivity"),
     "re": (BLUE, "s", False, "pre-registered re-test (already-analysed data)"), "exp": (AQUA, "D", True, "exploratory (development years)"),
     "post": (VIOLET, "^", True, "sensitivity (post-hoc)")}
blocks = [("Development 2010–2019", [("CV$_{\\rm box}$ twins", 1.966, 1.4737, 3.1731, "81", "exp")]),
          ("Held-out 2021, 2023, 2024", [("CV$_{\\rm box}$ twins", 1.3057, 0.9367, 2.2182, "40", "re"),
                                         ("same flare-history twins", 1.1020, 0.6525, 1.7098, "37", "re")]),
          ("EUV-unseen extra set (2021, 2023, 2024)", [("CV$_{\\rm box}$ twins", 1.6295, 0.7907, 3.8386, "23", "sec")]),
          ("2022 (never pooled)", [("CV$_{\\rm box}$ twins", 3.2350, 1.2554, 4.5452, "25", "sec")]),
          ("2025–26 confirmation (TEST 1)", [("PRIMARY: CV$_{\\rm box}$ twins", 3.2624, 1.2956, 9.4887, "50", "conf"),
                                              ("same flare-history twins", 2.8174, 1.0169, 6.8227, "47", "sec"),
                                              ("single-region pairs", 3.4426, 1.3626, 7.3045, "16", "sec"),
                                              ("pooled with 2021/23/24 (not a confirmation)", 1.8832, 1.2260, 3.3691, "90", "sec")]),
          ("2025–26, same ratio, other checks (post-hoc)", [("flare frames removed", 2.9247, 1.1771, 8.2515, "49", "post"),
                                                           ("CI resampled by false HARP", 3.2624, 1.4764, 8.9395, "50", "post"),
                                                           ("CI resampled by both HARPs", 3.2624, 0.8632, 12.2290, "50", "post"),
                                                           ("CI resampled by linked groups", 3.2624, 0.6812, 18.8683, "50", "post")])]
n = sum(len(r) + 1 for _, r in blocks)
fig, ax = plt.subplots(figsize=(FULL, 0.2 * n + 0.7))
yy = n; ticks, labs, bold = [], [], []
for bi, (title, rows) in enumerate(blocks):
    ticks.append(yy); labs.append(title); bold.append(True)
    if bi % 2 == 0:
        ax.axhspan(yy - len(rows) - 0.5, yy + 0.5, color=SOFT, lw=0, zorder=0)
    yy -= 1
    for lab, v, lo, hi, npair, st in rows:
        c, m, f, _ = S[st]
        if st == "conf":
            ax.axhspan(yy - 0.45, yy + 0.45, color=LBLUE, lw=0, zorder=0)
        ax.plot([lo, hi], [yy, yy], color=c, lw=1.5, solid_capstyle="round", zorder=2)
        ax.plot(v, yy, m, ms=6, mfc=c if f else "white", mec=c, mew=1.3, zorder=3)
        ax.text(26, yy, f"{v:.2f} [{lo:.2f}, {hi:.2f}]", va="center", fontsize=7, ha="left")
        ticks.append(yy); labs.append(f"{lab} ({npair})"); bold.append(False)
        yy -= 1
ax.axvline(1, color=INK, lw=0.9, ls="--", zorder=1)
ax.set_xscale("log"); ax.set_xlim(0.5, 75); ax.set_ylim(0.3, n + 0.7)
ax.set_xticks([0.5, 1, 2, 4, 8, 16]); ax.set_xticklabels(["0.5", "1", "2", "4", "8", "16"]); ax.minorticks_off()
ax.set_yticks(ticks); ax.set_yticklabels(labs, fontsize=7); ax.tick_params(axis="y", length=0)
for tl, bb in zip(ax.get_yticklabels(), bold):
    if bb: tl.set_fontweight("bold"); tl.set_color(INK)
ax.spines["left"].set_visible(False)
ax.text(26, n + 0.45, "ratio [95% CI]", fontsize=7, weight="bold", ha="left")
ax.set_xlabel("twins ratio = median CV$_{\\rm box}$ of true alarms ÷ median of their false twins (log scale; dashed line = no difference)")
for k in ("conf", "sec", "re", "exp", "post"):
    c, m, f, t = S[k]; ax.plot([], [], m, color=c, mfc=c if f else "white", mec=c, label=t)
ax.legend(loc="upper center", bbox_to_anchor=(0.35, -0.1), ncol=3, fontsize=6.5, handletextpad=0.3)
ax.grid(axis="x", color=GRID, lw=0.5)
save(fig, "R3_twins", "results_figs.py")

# ---------------------------------------------------------------- R4 filter trade-off
# weighted %: euv_confirm_filter_retest.log:8-11 and euv_extra_filter_test.log (models); C+ from docs/posthoc_2026-09-28.md:292,326
sets = [("(a) 2025–26 confirmation set (378)",
         {"A": (0.0, 100.0), "C": (31.02, 92.62), "A$_{\\rm CV}$": (63.12, 78.63), "C$_{\\rm CV}$": (55.07, 78.63), "C+": (38.9, 91.3)}),
        ("(b) EUV-unseen extra set (155)",
         {"A": (0.0, 100.0), "C": (17.01, 89.78), "A$_{\\rm CV}$": (60.20, 83.83), "C$_{\\rm CV}$": (52.32, 87.17), "C+": (26.9, 91.0)})]
col = {"A": INK2, "C": INK, "A$_{\\rm CV}$": ORANGE, "C$_{\\rm CV}$": ORANGE, "C+": VIOLET}
mk = {"A": "o", "C": "s", "A$_{\\rm CV}$": "^", "C$_{\\rm CV}$": "v", "C+": "*"}
fig, axs = plt.subplots(1, 2, figsize=(FULL, 2.9), sharey=True, gridspec_kw=dict(wspace=0.12))
for ax, (title, P) in zip(axs, sets):
    ax.axhspan(90, 101, color="#e8f3ec", lw=0, zorder=0)
    ax.axhline(88, color=AQUA, ls=":", lw=1.0); ax.text(-2.5, 86.6, "88% kept (target on 2010–2019)", fontsize=6.2, color=AQUA, ha="left")
    for k, (fx, ty) in P.items():
        ax.scatter(fx, ty, s=110 if k == "C+" else 52, marker=mk[k], color=col[k], zorder=4,
                   edgecolor="white" if k != "C+" else VIOLET, lw=0.6)
        dx, dy, ha = (2.2, 0.9, "left") if k not in ("A$_{\\rm CV}$",) else (2.2, -1.9, "left")
        if k == "C$_{\\rm CV}$": dy = 1.1
        ax.text(fx + dx, ty + dy, k + (" (post-hoc)" if k == "C+" else ""), fontsize=7, color=col[k], ha=ha)
    ax.annotate("", xy=P["C$_{\\rm CV}$"], xytext=P["C"], arrowprops=dict(arrowstyle="-|>", color=ORANGE, lw=0.9, alpha=0.8))
    ax.annotate("", xy=P["C+"], xytext=P["C"], arrowprops=dict(arrowstyle="-|>", color=VIOLET, lw=0.9, alpha=0.8))
    ax.set_xlim(-4, 72); ax.set_ylim(74, 102); ax.grid(color=GRID, lw=0.5); ax.set_axisbelow(True)
    ax.set_xlabel("false alarms removed (%, weighted)"); ax.set_title(title, loc="left", fontsize=8.2)
axs[0].set_ylabel("true alarms kept (%, weighted)")
axs[0].text(70, 75.2, "better: up and to the right", fontsize=6.3, color=INK2, style="italic", ha="right")
save(fig, "R4_filter", "results_figs.py")

# ---------------------------------------------------------------- R5 overlap (docs/posthoc_2026-09-28.md:225-238)
bins = ["0", "1", "2", "3–4", "5+"]; tr = [0.111, 0.237, 0.251, 0.243, 0.337]; fa = [0.056, 0.110, 0.152, 0.189, 0.286]
nt = [49, 40, 48, 55, 64]; nf = [626, 236, 169, 144, 101]
fig, ax = plt.subplots(figsize=(FULL * 0.72, 2.6))
x = np.arange(5)
ax.bar(x - 0.19, fa, 0.36, color="#cfcfcb", edgecolor=INK2, lw=0.5, label="false alarms (n = 1,276)")
ax.bar(x + 0.19, tr, 0.36, color=ORANGE, edgecolor=ORANGE, lw=0.5, label="true alarms (n = 256)")
for i in x:
    ax.text(i - 0.19, fa[i] + 0.006, f"{nf[i]}", ha="center", fontsize=6.2, color=INK2)
    ax.text(i + 0.19, tr[i] + 0.006, f"{nt[i]}", ha="center", fontsize=6.2, color=ORANGE)
ax.set_xticks(x); ax.set_xticklabels(bins); ax.set_xlabel("C-class flares in the 24 h before the alarm")
ax.set_ylabel("median CV$_{\\rm box}$"); ax.set_ylim(0, 0.39); ax.grid(axis="y", color=GRID, lw=0.5); ax.set_axisbelow(True)
ax.legend(loc="upper left", fontsize=6.8)
ax.set_title("POST-HOC; pooled over all five sets, includes 2022 (numbers on bars = episodes)", loc="left", fontsize=7, color=INK2)
save(fig, "R5_overlap", "results_figs.py")
print("done")
